<?php
require dirname(__DIR__).'/includes/bootstrap.php';
if(!str_starts_with(cfg('DB_NAME'),'seo_autopilot_test'))throw new RuntimeException('This suite requires an isolated test database.');
$base=cfg('APP_URL');$credentials=json_decode(file_get_contents(getenv('SEO_TEST_CREDENTIALS') ?: ROOT.'/storage/test-credentials.json'),true);$checks=0;$cookie=ROOT.'/storage/test-cookie.txt';
function http(string $path,?array $post=null,?string $jar=null): array {global $base,$cookie;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$jar??$cookie,CURLOPT_COOKIEFILE=>$jar??$cookie,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>30,CURLOPT_PROXY=>'']);if($post!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post]);$raw=curl_exec($c);if($raw===false)throw new RuntimeException(curl_error($c));$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);curl_close($c);return ['status'=>$status,'headers'=>substr($raw,0,$size),'body'=>substr($raw,$size)];}
function token(array $response): string {preg_match('/(?:name="csrf" value|name="csrf-token" content)="([a-f0-9]+)"/',$response['body'],$m);return $m[1]??'';}
function test(bool $ok,string $name): void {global $checks;if(!$ok)throw new RuntimeException('FAIL '.$name);echo 'PASS '.$name."\n";$checks++;}
function api_test(string $action,array $data,int $expected=200): array {global $csrf;$r=http('/api/v1/'.$action,['csrf'=>$csrf]+$data);test($r['status']===$expected,$action.' HTTP '.$expected.($r['status']!==$expected?' got '.$r['status'].' '.strip_tags($r['body']):''));return json_decode($r['body'],true)??[];}
