$report=api_test('report',['website_id'=>$wid]);$rid=(int)value('SELECT id FROM reports WHERE website_id=? ORDER BY id DESC LIMIT 1',[$wid]);test(http('/report?id='.$rid.'&website_id='.$wid)['status']===200,'Report view');$pdf=http('/report?id='.$rid.'&website_id='.$wid.'&pdf=1');test($pdf['status']===200&&str_starts_with($pdf['body'],'%PDF'),'PDF download');
